from typing import List


def factorize(n: int) -> List[int]:
    def smallest_factor(num):
        for i in range(2, int(num**0.5) + 1):
            if num % i:
                continue
            else:
                return i
        return num

    factors = []
    while n > 1:
        factor = smallest_factor(n)
        factors.append(factor)
        while n % factor == 0:
            n //= factor
    return factors

# Example usage:
